  const { NextRequest } = jest.requireMock('next/server');

  // Setup before each test
  beforeEach(() => {
    // Reset mocks
    jest.resetAllMocks();

    // Mock environment variables
    process.env = { ...originalEnv, AI_API_KEY: 'test-api-key' };
  });

  // Restore environment after tests
  afterAll(() => {
    process.env = originalEnv;
