'use client';

import { useState } from 'react';
import ImageUploader from '@/components/ImageUploader';
import ScreenAreaSelector from '@/components/ScreenAreaSelector';
import ResultDisplay from '@/components/ResultDisplay';
import { ScreenArea } from '@/lib/aiService';

export default function TestPage() {
  const [originalImage, setOriginalImage] = useState<string | null>(null);
  const [screenAreas, setScreenAreas] = useState<ScreenArea[]>([]);
  const [generatedImage, setGeneratedImage] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [apiKey, setApiKey] = useState<string>('');

  const handleImageUpload = (imageDataUrl: string) => {
    setOriginalImage(imageDataUrl);
    setScreenAreas([]);
    setGeneratedImage(null);
    setError(null);
  };

  const handleAreasSelected = (areas: ScreenArea[]) => {
    setScreenAreas(areas);
  };

  const handleGenerateVisualization = async () => {
    if (!originalImage) {
      setError('Please upload an image first');
      return;
    }

    if (!apiKey) {
      setError('Please enter an API key');
      return;
    }

    setIsLoading(true);
    setError(null);

    try {
      const response = await fetch('/api/visualize', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          originalImageBase64: originalImage,
          screenAreas: screenAreas.length > 0 ? screenAreas : undefined,
          apiKey,
        }),
      });

      const data = await response.json();

      if (!response.ok) {
        throw new Error(data.error || 'Failed to generate visualization');
      }

      setGeneratedImage(data.imageUrl);
    } catch (err: any) {
      setError(err.message || 'An unexpected error occurred');
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <main className="flex min-h-screen flex-col items-center p-8 max-w-6xl mx-auto">
      <h1 className="text-3xl font-bold mb-8">Home Screen Visualizer - Test Page</h1>

      <div className="w-full mb-8">
        <h2 className="text-xl font-semibold mb-4">1. Upload an Image</h2>
        <ImageUploader onImageUpload={handleImageUpload} />
      </div>

      {originalImage && (
        <div className="w-full mb-8">
          <h2 className="text-xl font-semibold mb-4">2. Select Window Areas (Optional)</h2>
          <ScreenAreaSelector
            imageUrl={originalImage}
            onAreasSelected={handleAreasSelected}
          />
        </div>
      )}

      {originalImage && (
        <div className="w-full mb-8">
          <h2 className="text-xl font-semibold mb-4">3. Generate Visualization</h2>

          <div className="flex flex-col gap-4 mb-4">
            <div>
              <label htmlFor="apiKey" className="block text-sm font-medium mb-1">
                API Key (OpenAI)
              </label>
              <input
                id="apiKey"
                type="password"
                value={apiKey}
                onChange={(e) => setApiKey(e.target.value)}
                className="w-full p-2 border border-gray-300 rounded-lg"
                placeholder="Enter your OpenAI API key"
              />
            </div>

            <button
              type="button"
              onClick={handleGenerateVisualization}
              disabled={!originalImage || isLoading}
              className="py-3 px-4 bg-green-600 text-white rounded-lg hover:bg-green-700 focus:outline-none focus:ring-2 focus:ring-green-500 disabled:bg-gray-400 disabled:cursor-not-allowed"
            >
              {isLoading ? 'Generating...' : 'Generate Visualization'}
            </button>
          </div>
        </div>
      )}

      {originalImage && (
        <div className="w-full">
          <ResultDisplay
            originalImageUrl={originalImage}
            generatedImageUrl={generatedImage}
            isLoading={isLoading}
            error={error}
          />
        </div>
      )}
    </main>
  );
}

import { render, screen, fireEvent } from '@testing-library/react';
import ImageUploader from './ImageUploader';

describe('ImageUploader', () => {
  const mockOnImageUpload = jest.fn();

  beforeEach(() => {
    jest.resetAllMocks();
  });

  it('renders the upload button', () => {
    render(<ImageUploader onImageUpload={mockOnImageUpload} />);

    const uploadButton = screen.getByLabelText('Upload an image');
    expect(uploadButton).toBeInTheDocument();
  });

  it('shows file input when button is clicked', () => {
    render(<ImageUploader onImageUpload={mockOnImageUpload} />);

    const uploadButton = screen.getByLabelText('Upload an image');
    const fileInput = screen.getByRole('textbox', { hidden: true });

    // File input should be hidden
    expect(fileInput).toHaveClass('hidden');

    // Mock the click event
    fireEvent.click(uploadButton);

    // File input should still exist
    expect(fileInput).toBeInTheDocument();
  });

  it('calls onImageUpload when a valid file is selected', () => {
    // Mock FileReader
    const originalFileReader = window.FileReader;
    const mockFileReaderInstance = {
      readAsDataURL: jest.fn(),
      onload: null as any,
      onerror: null as any,
      result: 'data:image/jpeg;base64,test123',
    };

    window.FileReader = jest.fn(() => mockFileReaderInstance) as any;

    render(<ImageUploader onImageUpload={mockOnImageUpload} />);

    const fileInput = screen.getByRole('textbox', { hidden: true });

    // Create a mock file
    const file = new File(['test'], 'test.jpg', { type: 'image/jpeg' });

    // Trigger file selection
    fireEvent.change(fileInput, { target: { files: [file] } });

    // Simulate FileReader onload
    if (mockFileReaderInstance.onload) {
      mockFileReaderInstance.onload({ target: mockFileReaderInstance } as any);
    }

    // Check if onImageUpload was called with the correct data URL
    expect(mockOnImageUpload).toHaveBeenCalledWith('data:image/jpeg;base64,test123');

    // Restore original FileReader
    window.FileReader = originalFileReader;
  });

  it('shows an error when file type is invalid', () => {
    render(<ImageUploader onImageUpload={mockOnImageUpload} acceptedFormats={['image/jpeg']} />);

    const fileInput = screen.getByRole('textbox', { hidden: true });

    // Create a mock file with invalid type
    const file = new File(['test'], 'test.txt', { type: 'text/plain' });

    // Trigger file selection
    fireEvent.change(fileInput, { target: { files: [file] } });

    // Check if error message is displayed
    const errorMessage = screen.getByRole('alert');
    expect(errorMessage).toBeInTheDocument();
    expect(errorMessage).toHaveTextContent(/invalid file type/i);

    // onImageUpload should not be called
    expect(mockOnImageUpload).not.toHaveBeenCalled();
  });

  it('shows an error when file size exceeds the limit', () => {
    render(<ImageUploader onImageUpload={mockOnImageUpload} maxSizeInMB={0.0001} />);

    const fileInput = screen.getByRole('textbox', { hidden: true });

    // Create a mock file with size larger than the limit
    const file = new File(['test'], 'test.jpg', { type: 'image/jpeg' });
    Object.defineProperty(file, 'size', { value: 1000 }); // 1KB

    // Trigger file selection
    fireEvent.change(fileInput, { target: { files: [file] } });

    // Check if error message is displayed
    const errorMessage = screen.getByRole('alert');
    expect(errorMessage).toBeInTheDocument();
    expect(errorMessage).toHaveTextContent(/file size exceeds/i);

    // onImageUpload should not be called
    expect(mockOnImageUpload).not.toHaveBeenCalled();
  });
});

import { useState, useRef, ChangeEvent } from 'react';

interface ImageUploaderProps {
  onImageUpload: (imageDataUrl: string) => void;
  maxSizeInMB?: number;
  acceptedFormats?: string[];
}

/**
 * Component for uploading and previewing images
 */
export default function ImageUploader({
  onImageUpload,
  maxSizeInMB = 5,
  acceptedFormats = ['image/jpeg', 'image/png', 'image/webp'],
}: ImageUploaderProps) {
  const [previewUrl, setPreviewUrl] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Convert maxSizeInMB to bytes
  const maxSizeInBytes = maxSizeInMB * 1024 * 1024;

  // Format the accepted formats for the file input
  const acceptString = acceptedFormats.join(',');

  /**
   * Handle file selection
   */
  const handleFileChange = (event: ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    setError(null);

    // Validate file selection
    if (!file) {
      setError('No file selected');
      return;
    }

    // Validate file type
    if (!acceptedFormats.includes(file.type)) {
      setError(`Invalid file type. Accepted formats: ${acceptedFormats.join(', ')}`);
      return;
    }

    // Validate file size
    if (file.size > maxSizeInBytes) {
      setError(`File size exceeds the maximum limit of ${maxSizeInMB}MB`);
      return;
    }

    // Read the file as a data URL
    const reader = new FileReader();
    reader.onload = (e) => {
      const dataUrl = e.target?.result as string;
      setPreviewUrl(dataUrl);
      onImageUpload(dataUrl);
    };
    reader.onerror = () => {
      setError('Error reading the file');
    };
    reader.readAsDataURL(file);
  };

  /**
   * Trigger file selection dialog
   */
  const handleButtonClick = () => {
    fileInputRef.current?.click();
  };

  return (
    <div className="flex flex-col items-center gap-4 w-full max-w-md">
      <div className="w-full">
        <button
          type="button"
          onClick={handleButtonClick}
          className="w-full py-3 px-4 bg-blue-600 text-white rounded-lg hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-blue-500"
          aria-label="Upload an image"
        >
          Upload Image
        </button>
        <input
          ref={fileInputRef}
          type="file"
          accept={acceptString}
          onChange={handleFileChange}
          className="hidden"
          role="textbox"
        />
      </div>

      {error && (
        <div className="w-full p-3 bg-red-100 text-red-700 rounded-lg" role="alert">
          {error}
        </div>
      )}

      {previewUrl && (
        <div className="w-full">
          <h3 className="text-lg font-medium mb-2">Preview</h3>
          <div className="relative aspect-video w-full overflow-hidden rounded-lg border border-gray-300">
            <img
              src={previewUrl}
              alt="Preview of uploaded image"
              className="object-contain w-full h-full"
            />
          </div>
        </div>
      )}
    </div>
  );
}

interface ResultDisplayProps {
